self.onmessage=async({data:e})=>{try{const t=65536,a=[...new Set([0,Math.max(0,Math.floor((e.size-t)/2)),Math.max(0,e.size-t)])],r=await Promise.all(a.map(a=>e.slice(a,a+t).arrayBuffer())),s=(new TextEncoder).encode(`${e.size}:`),n=new Uint8Array(s.length+r.reduce((e,t)=>e+t.byteLength,0));n.set(s);let o=s.length;for(const e of r)n.set(new Uint8Array(e),o),o+=e.byteLength;const i=await crypto.subtle.digest("SHA-256",n);self.postMessage({fingerprint:Array.from(new Uint8Array(i),e=>e.toString(16).padStart(2,"0")).join("")})}catch(e){self.postMessage({error:e.message})}};